use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// Hosts the `HTTPClient<[...]>` handle is scoped to. A request outside this
/// set is a trap at the boundary, so it is refused here as a recorded failure.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extracts the lowercase host from an http(s) URL, or `None` if the URL is
/// malformed or carries userinfo or whitespace.
fn host_of(url: &str) -> Option<String> {
    if url.chars().any(|c| c.is_control() || c.is_whitespace()) {
        return None;
    }
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(['/', '?', '#']).next()?;
    if authority.contains('@') {
        return None;
    }
    let host = match authority.rsplit_once(':') {
        Some((h, port)) if port.chars().all(|c| c.is_ascii_digit()) => h,
        _ => authority,
    };
    if host.is_empty() {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            let allowed = host_of(&url)
                .is_some_and(|h| ALLOWED_HOSTS.contains(&h.as_str()));
            if !allowed {
                failures.push(FetchFailure {
                    url,
                    error: "host not in allowlist".to_string(),
                });
                continue;
            }

            // `fetch` returns transport failures as values, so one dead feed
            // does not fail the whole batch.
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
